// Sync the reader library into public/ (item 9).
//
// `src/lib/reader/reader.js` + `Readability.js` are the single source of
// truth. `public/lib/` used to hold byte-identical committed copies that
// had to be updated by hand — they are now generated by this script
// before dev/build (predev/prebuild), and git-ignored. Vite serves
// public/ as-is in dev and the copy-static-files plugin copies public/lib
// into dist/ at build time, so nothing downstream changes.
const fs = require('fs');
const path = require('path');

const files = ['reader.js', 'Readability.js'];
const srcDir = path.resolve(__dirname, '../src/lib/reader');
const destDir = path.resolve(__dirname, '../public/lib');

fs.mkdirSync(destDir, { recursive: true });

for (const file of files) {
  const src = path.join(srcDir, file);
  const dest = path.join(destDir, file);
  fs.copyFileSync(src, dest);
  console.log(`[sync-reader-lib] public/lib/${file} <- src/lib/reader/${file}`);
}
